previewCss:
.darma-loader-darma-b13-barbell-lift { --accent: var(--loader-color, #1d4ed8); --accent-2: var(--loader-secondary-color, #0ea5e9); width: var(--loader-size, 116px); height: calc(var(--loader-size, 116px) * .68); position: relative; }
.darma-loader-darma-b13-barbell-lift::before, .darma-loader-darma-b13-barbell-lift::after { content: ''; position: absolute; bottom: 0; width: 6%; height: 100%; border-radius: 3px; background: linear-gradient(#cbd5e1, #64748b); }
.darma-loader-darma-b13-barbell-lift::before { left: 9%; }
.darma-loader-darma-b13-barbell-lift::after { right: 9%; }
.darma-loader-darma-b13-barbell-lift .darma-loader-darma-b13-barbell-lift__bar { position: absolute; left: 3%; width: 94%; height: 7%; border-radius: 999px; background: linear-gradient(#f1f5f9, #94a3b8); animation: darma-loader-darma-b13-barbell-lift-lift calc(var(--loader-speed, 1s) * 2.4) ease-in-out infinite; }
.darma-loader-darma-b13-barbell-lift .darma-loader-darma-b13-barbell-lift__bar::before, .darma-loader-darma-b13-barbell-lift .darma-loader-darma-b13-barbell-lift__bar::after { content: ''; position: absolute; top: -170%; width: 11%; height: 440%; border-radius: 4px; background: linear-gradient(var(--accent), var(--accent-2)); }
.darma-loader-darma-b13-barbell-lift .darma-loader-darma-b13-barbell-lift__bar::before { left: 0; }
.darma-loader-darma-b13-barbell-lift .darma-loader-darma-b13-barbell-lift__bar::after { right: 0; }
@keyframes darma-loader-darma-b13-barbell-lift-lift { 0%, 100% { bottom: 14%; } 46%, 54% { bottom: 72%; } }

